/* DAWAH X — darimi, অধ্যায় 5 · খণ্ড 5 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['darimi'][5]=[[801,801,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَدَعُ الصَّلَاةَ أَيَّامَ حَيْضِهَا مِنْ الشَّهْرِ ثُمَّ تَغْتَسِلُ مِنْ الظُّهْرِ إِلَى الظُّهْرِ وَتَوَضَّأُ عِنْدَ كُلِّ صَلَاةٍ وَتَصُومُ وَتُصَلِّي وَيَأْتِيهَا زَوْجُهَا ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَعَطَاءٍ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[802,802,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏قَمِيرَ ‏ ‏امْرَأَةِ ‏ ‏مَسْرُوقٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَغْتَسِلُ كُلَّ يَوْمٍ مَرَّةً ‏","","",""],[803,803,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَرْوَانُ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ مَعْرُوفٍ ‏ ‏عَنْ ‏ ‏مُقَاتِلِ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ يَقُولُ فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَغْتَسِلُ مِنْ ظُهْرٍ إِلَى ظُهْرٍ ‏ ‏قَالَ ‏ ‏مَرْوَانُ ‏ ‏وَهُوَ قَوْلُ ‏ ‏الْأَوْزَاعِيِّ ‏","","",""],[804,804,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَغْتَسِلُ كُلَّ يَوْمٍ عِنْدَ صَلَاةِ الْأُولَى ‏","","",""],[805,805,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ هُوَ ابْنُ بَشِيرٍ الْجَزَرِيُّ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏لَمْ يَرَ بَأْسًا أَنْ ‏ ‏يَأْتِيَهَا ‏ ‏زَوْجُهَا ‏","","",""],[806,806,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَالِمٍ الْأَفْطَسِ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏أَتُجَامَعُ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏فَقَالَ ‏ ‏الصَّلَاةُ أَعْظَمُ مِنْ الْجِمَاعِ ‏","","",""],[807,807,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏يَأْتِيهَا ‏ ‏زَوْجُهَا ‏","","",""],[808,808,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏قَالَ ‏ ‏يَغْشَاهَا ‏ ‏زَوْجُهَا ‏","","",""],[809,809,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏يَغْشَاهَا ‏ ‏زَوْجُهَا وَإِنْ قَطَرَ الدَّمُ عَلَى الْحَصِيرِ ‏","","",""],[810,810,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِبَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏إِنَّ ‏ ‏الْحَجَّاجَ بْنَ يُوسُفَ ‏ ‏يَقُولُ إِنَّ ‏ ‏الْمُسْتَحَاضَةَ ‏ ‏لَا ‏ ‏يَغْشَاهَا ‏ ‏زَوْجُهَا ‏ ‏قَالَ ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ الْمُزَنِيُّ ‏ ‏الصَّلَاةُ أَعْظَمُ حُرْمَةً ‏ ‏يَغْشَاهَا ‏ ‏زَوْجُهَا ‏","","",""],[811,811,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏يَأْتِيهَا ‏ ‏زَوْجُهَا ‏","","",""],[812,812,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏يُجَامِعُهَا زَوْجُهَا تَدَعُ الصَّلَاةَ أَيَّامَ حَيْضِهَا فَإِذَا حَلَّتْ لَهَا الصَّلَاةُ ‏ ‏فَلْيَطَأْهَا ‏","","",""],[813,813,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ زُرْعَةَ الْخَارِفِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏يُجَامِعُهَا زَوْجُهَا ‏","","",""],[814,814,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَالْحَسَنِ ‏ ‏وَعَطَاءٍ ‏ ‏قَالُوا ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَغْتَسِلُ وَتُصَلِّي وَتَصُومُ رَمَضَانَ ‏ ‏وَيَغْشَاهَا ‏ ‏زَوْجُهَا ‏","","",""],[815,815,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏حَفْصٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏كَانَ يَقُولُ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏لَا ‏ ‏يَغْشَاهَا ‏ ‏زَوْجُهَا ‏ ‏قَالَ ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ لِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏لَا أَعْلَمُ أَحَدًا قَالَ هَذَا عَنْ ‏ ‏الْحَسَنِ ‏","","",""],[816,816,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُحَمَّدٌ ‏ ‏يَكْرَهُ أَنْ ‏ ‏يَغْشَى ‏ ‏الرَّجُلُ امْرَأَتَهُ وَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[817,817,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏لَا ‏ ‏يَأْتِيهَا ‏ ‏زَوْجُهَا وَلَا تَصُومُ وَلَا تَمَسُّ الْمُصْحَفَ ‏","","",""],[818,818,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ الْأَعْوَرُ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏قَمِيرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏لَا ‏ ‏يَأْتِيهَا ‏ ‏زَوْجُهَا ‏","","",""],[819,819,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏كَانَ يُقَالُ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏لَا تُجَامَعُ وَلَا تَصُومُ وَلَا تَمَسُّ الْمُصْحَفَ إِنَّمَا رُخِّصَ لَهَا فِي الصَّلَاةِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏يُجَامِعُهَا زَوْجُهَا وَيَحِلُّ لَهَا مَا يَحِلُّ لِلطَّاهِرِ ‏","","",""],[820,820,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏تُمْسِكُ الْمَرْأَةُ عَنْ الصَّلَاةِ فِي حَيْضِهَا سَبْعًا فَإِنْ طَهُرَتْ فَذَاكَ وَإِلَّا أَمْسَكَتْ مَا بَيْنَهَا وَبَيْنَ الْعَشْرِ فَإِنْ طَهُرَتْ فَذَاكَ وَإِلَّا اغْتَسَلَتْ وَصَلَّتْ وَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[821,821,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الرَّبِيعِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏الْحَيْضُ عَشْرٌ فَمَا زَادَ فَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏ ‏و قَالَ ‏ ‏عَطَاءٌ ‏ ‏الْحَيْضُ خَمْسَ عَشْرَةَ ‏","","",""],[822,822,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْجَلْدِ بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي إِيَاسٍ مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏الْحَيْضُ عَشْرَةٌ فَمَا زَادَ فَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[823,823,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏الْحَيْضُ إِلَى ثَلَاثَ عَشْرَةَ فَمَا زَادَ فَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[824,824,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏الْجَلْدِ بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏الْحَيْضُ عَشْرَةُ أَيَّامٍ ثُمَّ هِيَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[825,825,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏الْحَيْضُ إِلَى ثَلَاثَةَ عَشَرَ يَوْمًا فَمَا سِوَى ذَلِكَ فَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[826,826,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا رَأَتْ الدَّمَ فَإِنَّهَا تُمْسِكُ عَنْ الصَّلَاةِ بَعْدَ أَيَّامِ حَيْضِهَا يَوْمًا أَوْ يَوْمَيْنِ ثُمَّ هِيَ بَعْدَ ذَلِكَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[827,827,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْجَلْدِ بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَنْتَظِرُ ثَلَاثًا أَرْبَعًا خَمْسًا سِتًّا سَبْعًا ثَمَانِيًا تِسْعًا عَشْرًا ‏","","",""],[828,828,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏بَلَغَنَا أَنَّ ‏ ‏الْمُسْتَحَاضَةَ ‏ ‏تَنْتَظِرُ أَعْلَى ‏ ‏أَقْرَائِهَا ‏ ‏بِيَوْمٍ ‏","","",""],[829,829,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏الرَّبِيعُ بْنُ صَبِيحٍ ‏ ‏عَنْ ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا زَادَ عَلَى الْعَشْرِ فَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[830,830,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏مُفَضَّلِ بْنِ مُهَلْهَلٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏أَقْصَى الْحَيْضِ خَمْسَ عَشْرَةَ ‏","","",""],[831,831,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ قَالَ ‏ ‏سُفْيَانُ ‏ ‏بَلَغَنِي ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَدْنَى الْحَيْضِ ثَلَاثَةُ أَيَّامٍ ‏ ‏سُئِلَ ‏ ‏عَبْدُ اللَّهِ الدَّارِمِيُّ ‏ ‏تَأْخُذُ بِهَذَا ‏ ‏قَالَ ‏ ‏نَعَمْ إِذَا كَانَ عَادَتَهَا وَسَأَلْتُهُ أَيْضًا عَنْ هَذَا قَالَ أَقَلُّ الْحَيْضِ يَوْمٌ وَلَيْلَةٌ وَأَكْثَرُهُ خَمْسَ عَشْرَةَ ‏","","",""],[832,832,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي زَكَرِيَّا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هُوَ ‏ ‏أَبُو سَعْدٍ الصَّغَّانِيُّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الرَّبِيعِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏أَدْنَى الْحَيْضِ ثَلَاثٌ ‏","","",""],[833,833,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏مَخْلَدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏أَدْنَى الْحَيْضِ يَوْمٌ ‏","","",""],[834,834,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا رَأَتْ الدَّمَ قَبْلَ حَيْضِهَا يَوْمًا أَوْ يَوْمَيْنِ فَهُوَ مِنْ الْحَيْضِ ‏","","",""],[835,835,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَقَيْسِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏أَنَّهُمَا قَالَا ‏ ‏فِي الْبِكْرِ إِذَا نَفِسَتْ ‏ ‏فَاسْتُحِيضَتْ ‏ ‏قَالَا تُمْسِكُ عَنْ الصَّلَاةِ مِثْلَ مَا تُمْسِكُ الْمَرْأَةُ مِنْ نِسَائِهَا ‏","","",""],[836,836,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ قَالَ ‏ ‏سُفْيَانُ ‏ ‏إِذَا كَانَتْ الْمَرْأَةُ أَوَّلَ مَا تَحِيضُ تَجْلِسُ فِي الْحَيْضِ مِنْ نَحْوِ نِسَائِهَا ‏ ‏سُئِلَ ‏ ‏عَبْد اللَّهِ ‏ ‏عَنْ هَذَا ‏ ‏فَقَالَ ‏ ‏هُوَ أَشْبَهُ الْأَشْيَاءِ ‏","","",""],[837,837,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْكَبِيرَةِ ‏ ‏تَرَى الدَّمَ قَالَ لَا ‏ ‏نَرَاهُ حَيْضًا ‏","","",""],[838,838,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنِيهِ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي امْرَأَةٍ تَرَكَهَا الْحَيْضُ ثَلَاثِينَ سَنَةً ثُمَّ رَأَتْ الدَّمَ فَأَمَرَ فِيهَا بِشَأْنِ ‏ ‏الْمُسْتَحَاضَةِ ‏","","",""],[839,839,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْكَبِيرَةِ ‏ ‏تَرَى الدَّمَ قَالَ هِيَ بِمَنْزِلَةِ ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَفْعَلُ كَمَا تَفْعَلُ ‏ ‏الْمُسْتَحَاضَةُ ‏","","",""],[840,840,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَالْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏فِي الَّتِي قَعَدَتْ مِنْ الْمَحِيضِ إِذَا رَأَتْ الدَّمَ تَوَضَّأَتْ وَصَلَّتْ وَلَا تَغْتَسِلُ ‏ ‏سُئِلَ ‏ ‏عَبْد اللَّهِ ‏ ‏عَنْ الْكَبِيرَةِ ‏ ‏قَالَ ‏ ‏تَوَضَّأُ وَتُصَلِّي وَإِذَا طُلِّقَتْ تَعْتَدُّ بِالْأَشْهُرِ ‏","","",""],[841,841,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ قَالَ ‏ ‏سُفْيَانُ ‏ ‏الطُّهْرُ خَمْسُ عَشْرَةَ ‏","","",""],[842,842,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِذَا حَاضَتْ الْمَرْأَةُ فِي شَهْرٍ أَوْ فِي أَرْبَعِينَ لَيْلَةً ثَلَاثَ حِيَضٍ فَإِذَا شَهِدَ لَهَا الشُّهُودُ الْعُدُولُ مِنْ النِّسَاءِ أَنَّهَا رَأَتْ مَا يُحَرِّمُ عَلَيْهَا الصَّلَاةَ مِنْ ‏ ‏طُمُوثِ ‏ ‏النِّسَاءِ الَّذِي هُوَ ‏ ‏الطَّمْثُ ‏ ‏الْمَعْرُوفُ فَقَدْ خَلَا أَجَلُهَا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏سَمِعْت ‏ ‏يَزِيدَ بْنَ هَارُونَ ‏ ‏يَقُولُ ‏ ‏أَسْتَحِبُّ الطُّهْرَ خَمْسَ عَشْرَةَ ‏","","",""],[843,843,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏جَاءَتْ امْرَأَةٌ إِلَى ‏ ‏عَلِيٍّ ‏ ‏تُخَاصِمُ زَوْجَهَا طَلَّقَهَا فَقَالَتْ قَدْ حِضْتُ فِي شَهْرٍ ثَلَاثَ حِيَضٍ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏لِشُرَيْحٍ ‏ ‏اقْضِ بَيْنَهُمَا ‏ ‏قَالَ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ وَأَنْتَ هَا هُنَا قَالَ اقْضِ بَيْنَهُمَا قَالَ يَا أَمِيرَ الْمُؤْمِنِينَ وَأَنْتَ هَا هُنَا قَالَ اقْضِ بَيْنَهُمَا قَالَ ‏ ‏إِنْ جَاءَتْ مِنْ ‏ ‏بِطَانَةِ ‏ ‏أَهْلِهَا مِمَّنْ ‏ ‏يُرْضَى دِينُهُ وَأَمَانَتُهُ تَزْعُمُ أَنَّهَا حَاضَتْ ثَلَاثَ حِيَضٍ تَطْهُرُ عِنْدَ كُلِّ ‏ ‏قُرْءٍ ‏ ‏وَتُصَلِّي جَازَ لَهَا وَإِلَّا فَلَا ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏قَالُونُ ‏ ‏وَقَالُونُ بِلِسَانِ ‏ ‏الرُّومِ ‏ ‏أَحْسَنْتَ ‏","","",""],[844,844,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ { ‏وَلَا يَحِلُّ لَهُنَّ أَنْ يَكْتُمْنَ مَا خَلَقَ اللَّهُ فِي أَرْحَامِهِنَّ ‏} ‏قَالَ الْحَيْضُ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏أَتَقُولُ بِهَذَا ‏ ‏قَالَ ‏ ‏لَا ‏ ‏سُئِلَ ‏ ‏عَبْد اللَّهِ ‏ ‏عَنْ حَدِيثِ ‏ ‏شُرَيْحٍ ‏ ‏تَقُولُ بِهِ ‏ ‏قَالَ ‏ ‏لَا وَقَالَ ثَلَاثُ حِيَضٍ فِي الشَّهْرِ كَيْفَ يَكُونُ ‏","","",""],[845,845,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏عَائِشَةُ ‏ ‏تَنْهَى النِّسَاءَ أَنْ يَنْظُرْنَ لَيْلًا فِي الْمَحِيضِ وَتَقُولُ إِنَّهُ قَدْ يَكُونُ الصُّفْرَةَ ‏ ‏وَالْكُدْرَةَ ‏","","",""],[846,846,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَوْلَاةِ عَمْرَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏عَمْرَةُ ‏ ‏تَأْمُرُ النِّسَاءَ أَنْ لَا يَغْتَسِلْنَ حَتَّى تَخْرُجَ الْقُطْنَةُ بَيْضَاءَ ‏","","",""],[847,847,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ قَالَ ‏ ‏سُفْيَانُ ‏ ‏الْكُدْرَةُ ‏ ‏وَالصُّفْرَةُ فِي أَيَّامِ الْحَيْضِ حَيْضٌ وَكُلُّ شَيْءٍ رَأَتْهُ بَعْدَ أَيَّامِ الْحَيْضِ مِنْ دَمٍ أَوْ ‏ ‏كُدْرَةٍ ‏ ‏أَوْ صُفْرَةٍ فَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏ ‏سُئِلَ ‏ ‏تَأْخُذُ بِقَوْلِ ‏ ‏سُفْيَانَ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[848,848,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏صَاحِبَتِهِ ‏ ‏فَاطِمَةَ بِنْتِ مُحَمَّدٍ ‏ ‏وَكَانَتْ فِي حِجْرِ ‏ ‏عَمْرَةَ ‏ ‏قَالَتْ ‏ ‏أَرْسَلَتْ امْرَأَةٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏إِلَى ‏ ‏عَمْرَةَ ‏ ‏بِكُرْسُفَةِ ‏ ‏قُطْنٍ فِيهَا كَالصُّفْرَةِ تَسْأَلُهَا هَلْ ‏ ‏تَرَى إِذَا لَمْ تَرَ الْمَرْأَةُ مِنْ الْحِيضَةِ إِلَّا هَذَا أَنْ قَدْ طَهُرَتْ ‏ ‏فَقَالَتْ ‏ ‏لَا حَتَّى ‏ ‏تَرَى الْبَيَاضَ خَالِصًا ‏","","",""],[849,849,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏كُنَّا نَكُونُ فِي حِجْرِهَا ‏ ‏فَكَانَتْ إِحْدَانَا تَحِيضُ ثُمَّ تَطْهُرُ فَتَغْتَسِلُ وَتُصَلِّي ثُمَّ تَنْكُسُهَا الصُّفْرَةُ الْيَسِيرَةُ فَتَأْمُرُنَا أَنْ نَعْتَزِلَ الصَّلَاةَ حَتَّى لَا نَرَى إِلَّا الْبَيَاضَ خَالِصًا ‏","","",""],[850,850,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏الْكُدْرَةُ ‏ ‏وَالصُّفْرَةُ وَالدَّمُ فِي أَيَّامِ الْحَيْضِ بِمَنْزِلَةِ الْحَيْضِ ‏","","",""],[851,851,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى بْنِ عُبَيْدٍ الدِّمَشْقِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِذَا رَأَتْ الدَّمَ فَلْتُمْسِكْ عَنْ الصَّلَاةِ حَتَّى ‏ ‏تَرَى الطُّهْرَ أَبْيَضَ كَالْقَصَّةِ ثُمَّ لِتَغْتَسِلْ وَتُصَلِّي ‏","","",""],[852,852,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏قَالَ كَانَ ‏ ‏الْحَسَنُ ‏ ‏لَا يَعُدُّ الصُّفْرَةَ ‏ ‏وَالْكُدْرَةَ ‏ ‏وَلَا مِثْلَ غُسَالَةِ اللَّحْمِ شَيْئًا ‏","","",""],[853,853,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أُمِّ عَطِيَّةَ ‏ ‏قَالَتْ ‏ ‏كُنَّا ‏ ‏لَا نَعُدُّ الصُّفْرَةَ ‏ ‏وَالْكُدْرَةَ ‏ ‏شَيْئًا ‏","","",""],[854,854,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الْمَرْأَةِ ‏ ‏تَرَى الدَّمَ فِي أَيَّامِ طُهْرِهَا ‏ ‏قَالَ ‏ ‏أَرَى أَنْ تَغْتَسِلَ وَتُصَلِّيَ ‏ ‏و قَالَ ‏ ‏ابْنُ سِيرِينَ ‏ ‏لَمْ يَكُونُوا يَرَوْنَ ‏ ‏بِالْكُدْرَةِ ‏ ‏وَالصُّفْرَةِ بَأْسًا ‏","","",""],[855,855,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْحَنَفِيَّةِ ‏ ‏فِي الْمَرْأَةِ ‏ ‏تَرَى الصُّفْرَةَ بَعْدَ الطُّهْرِ ‏ ‏قَالَ ‏ ‏تِلْكَ ‏ ‏التَّرِيَّةُ ‏ ‏تَغْسِلُهُ وَتَوَضَّأُ وَتُصَلِّي ‏","","",""],[856,856,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏وَحَجَّاجٌ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏وَحُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏لَيْسَ فِي التَّرِيَّةِ شَيْءٌ بَعْدَ الْغُسْلِ إِلَّا الطُّهُورُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏التَّرِيَّةُ الصُّفْرَةُ وَالْكُدْرَةُ ‏","","",""],[857,857,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا رَأَتْ الْمَرْأَةُ ‏ ‏التَّرِيَّةَ ‏ ‏بَعْدَ الْغُسْلِ بِيَوْمٍ أَوْ يَوْمَيْنِ فَإِنَّهَا ‏ ‏تَطَهَّرُ وَتُصَلِّي ‏","","",""],[858,858,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏لَيْسَ فِي ‏ ‏التَّرِيَّةِ ‏ ‏بَعْدَ الْغُسْلِ إِلَّا الطُّهُورُ ‏","","",""],[859,859,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أُمِّ الْهُذَيْلِ ‏ ‏عَنْ ‏ ‏أُمِّ عَطِيَّةَ ‏ ‏وَكَانَتْ قَدْ بَايَعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنَّا ‏ ‏لَا نَعْتَدُّ ‏ ‏بِالْكُدْرَةِ ‏ ‏وَالصُّفْرَةِ بَعْدَ الْغُسْلِ شَيْئًا ‏","","",""],[860,860,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا رَأَتْ الْحَائِضُ دَمًا ‏ ‏عَبِيطًا ‏ ‏بَعْدَ الْغُسْلِ بِيَوْمٍ أَوْ يَوْمَيْنِ فَإِنَّهَا تُمْسِكُ عَنْ الصَّلَاةِ يَوْمًا ثُمَّ هِيَ بَعْدَ ذَلِكَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[861,861,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏إِذَا تَطَهَّرَتْ الْمَرْأَةُ مِنْ الْمَحِيضِ ثُمَّ رَأَتْ بَعْدَ الطُّهْرِ مَا ‏ ‏يَرِيبُهَا ‏ ‏فَإِنَّمَا هِيَ ‏ ‏رَكْضَةٌ ‏ ‏مِنْ الشَّيْطَانِ فِي الرَّحِمِ فَإِذَا رَأَتْ مِثْلَ ‏ ‏الرُّعَافِ ‏ ‏أَوْ قَطْرَةِ الدَّمِ أَوْ غُسَالَةِ اللَّحْمِ تَوَضَّأَتْ وُضُوءَهَا لِلصَّلَاةِ ثُمَّ تُصَلِّي فَإِنْ كَانَ دَمًا ‏ ‏عَبِيطًا ‏ ‏الَّذِي لَا خَفَاءَ بِهِ فَلْتَدَعْ الصَّلَاةَ ‏","","",""],[862,862,"","","‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏سَمِعْتُ ‏ ‏يَزِيدَ بْنَ هَارُونَ ‏ ‏يَقُولُ ‏ ‏إِذَا كَانَ أَيَّامُ الْمَرْأَةِ سَبْعَةً فَرَأَتْ الطُّهْرَ بَيَاضًا فَتَزَوَّجَتْ ثُمَّ رَأَتْ الدَّمَ مَا بَيْنَهَا وَبَيْنَ الْعَشْرِ فَالنِّكَاحُ جَائِزٌ صَحِيحٌ فَإِنْ رَأَتْ الطُّهْرَ دُونَ السَّبْعِ فَتَزَوَّجَتْ ثُمَّ رَأَتْ الدَّمَ فَلَا يَجُوزُ وَهُوَ حَيْضٌ ‏ ‏و سُئِلَ ‏ ‏عَبْد اللَّهِ ‏ ‏تَقُولُ بِهِ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[863,863,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏فِي الْمَرْأَةِ يَكُونُ حَيْضُهَا سِتَّةَ أَيَّامٍ أَوْ سَبْعَةَ أَيَّامٍ ثُمَّ ‏ ‏تَرَى ‏ ‏كُدْرَةً ‏ ‏أَوْ صُفْرَةً أَوْ ‏ ‏تَرَى الْقَطْرَةَ أَوْ الْقَطْرَتَيْنِ مِنْ الدَّمِ أَنَّ ذَلِكَ بَاطِلٌ وَلَا يَضُرُّهَا شَيْءٌ ‏","","",""],[864,864,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَطَاءً ‏ ‏عَنْ الْمَرْأَةِ تَغْتَسِلُ مِنْ الْحَيْضِ فَتَرَى الصُّفْرَةَ قَالَ ‏ ‏تَوَضَّأُ ‏ ‏وَتَنْضَحُ ‏","","",""],[865,865,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏قَالَ ‏ ‏تَدَعُ الصَّلَاةَ فِي قُرُوئِهَا ذَلِكَ يَوْمًا أَوْ يَوْمَيْنِ ثُمَّ تَغْتَسِلُ فَإِذَا كَانَ عِنْدَ الْأُولَى نَظَرَتْ فَإِنْ كَانَتْ ‏ ‏تَرِيَّةً ‏ ‏تَوَضَّأَتْ وَصَلَّتْ وَإِنْ كَانَ دَمًا أَخَّرَتْ الظُّهْرَ وَعَجَّلَتْ الْعَصْرَ ثُمَّ صَلَّتْهُمَا بِغُسْلٍ وَاحِدٍ فَإِذَا غَابَتْ الشَّمْسُ نَظَرَتْ فَإِنْ كَانَتْ ‏ ‏تَرِيَّةً ‏ ‏تَوَضَّأَتْ وَصَلَّتْ وَإِنْ كَانَ دَمًا أَخَّرَتْ الْمَغْرِبَ وَعَجَّلَتْ الْعِشَاءَ ثُمَّ صَلَّتْهُمَا بِغُسْلٍ وَاحِدٍ فَإِذَا طَلَعَ الْفَجْرُ نَظَرَتْ فَإِنْ كَانَتْ ‏ ‏تَرِيَّةً ‏ ‏تَوَضَّأَتْ وَصَلَّتْ وَإِنْ كَانَ دَمًا اغْتَسَلَتْ وَصَلَّتْ ‏ ‏الْغَدَاةَ ‏ ‏فِي كُلِّ يَوْمٍ وَلَيْلَةٍ ثَلَاثَ مَرَّاتٍ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏الْأَقْرَاءُ عِنْدِي الْحَيْضُ ‏","","",""],[866,866,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَكَفَ ‏ ‏وَاعْتَكَفَ ‏ ‏مَعَهُ بَعْضُ نِسَائِهِ وَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏ ‏تَرَى الدَّمَ فَرُبَّمَا وَضَعَتْ الطَّسْتَ تَحْتَهَا مِنْ الدَّمِ وَزَعَمَ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏رَأَتْ مَاءَ الْعُصْفُرِ فَقَالَتْ كَانَ هَذَا شَيْئًا كَانَتْ فُلَانَةُ تَجِدُهُ ‏","","",""],[867,867,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏الْحَجَّاجِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَطَاءً ‏ ‏عَنْ ‏ ‏الْمَرْأَةِ تَطْهُرُ مِنْ الْمَحِيضِ ثُمَّ ‏ ‏تَرَى الصُّفْرَةَ قَالَ تَوَضَّأُ ‏","","",""],[868,868,"","","‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏قَرَأْتُ عَلَى ‏ ‏زَيْدِ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ هُوَ ابْنُ أَنَسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُهُ عَنْ الْمَرْأَةِ كَانَ حَيْضُهَا سَبْعَةَ أَيَّامٍ فَزَادَتْ حَيْضَتُهَا قَالَ ‏ ‏تَسْتَظْهِرُ بِثَلَاثَةِ أَيَّامٍ ‏","","",""],[869,869,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَوَّامٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا طَهُرَتْ الْمَرْأَةُ فِي وَقْتِ صَلَاةٍ فَلَمْ تَغْتَسِلْ وَهِيَ قَادِرَةٌ عَلَى أَنْ تَغْتَسِلَ قَضَتْ تِلْكَ الصَّلَاةَ ‏","","",""],[870,870,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا صَلَّتْ الْمَرْأَةُ رَكْعَتَيْنِ ثُمَّ حَاضَتْ فَلَا تَقْضِي إِذَا طَهُرَتْ ‏","","",""],[871,871,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏الْمَعْمَرِيُّ أَبُو سُفْيَانَ مُحَمَّدُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْمَرْأَةِ تَطْهُرُ عِنْدَ الظُّهْرِ فَتُؤَخِّرُ غُسْلَهَا حَتَّى يَدْخُلَ وَقْتُ الْعَصْرِ قَالَا تَقْضِي الظُّهْرَ ‏","","",""],[872,872,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَمُغِيرَةُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏وَعُبَيْدَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْمَرْأَةِ تُفَرِّطُ فِي الصَّلَاةِ حَتَّى يُدْرِكَهَا الْحَيْضُ قَالُوا تُعِيدُ تِلْكَ الصَّلَاةَ ‏","","",""],[873,873,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ أَبِي سُلَيْمَانَ ‏ ‏وَيُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي امْرَأَةٍ حَضَرَتْ الصَّلَاةُ فَفَرَّطَتْ حَتَّى حَاضَتْ قَالَا تَقْضِي تِلْكَ الصَّلَاةَ إِذَا اغْتَسَلَتْ ‏","","",""],[874,874,"","","‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَقَتَادَةَ ‏ ‏قَالَا ‏ ‏إِذَا ضَيَّعَتْ الْمَرْأَةُ الصَّلَاةَ حَتَّى تَحِيضَ فَعَلَيْهَا الْقَضَاءُ إِذَا طَهُرَتْ ‏","","",""],[875,875,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏إِذَا فَرَّطَتْ ثُمَّ حَاضَتْ قَضَتْ ‏","","",""],[876,876,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِي يُوسُفَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏إِذَا حَاضَتْ الْمَرْأَةُ فِي وَقْتِ الصَّلَاةِ فَلَيْسَ عَلَيْهَا الْقَضَاءُ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْقُوبُ هُوَ ابْنُ الْقَعْقَاعِ ‏ ‏قَاضِي ‏ ‏مَرْوٍ ‏ ‏وَأَبُو يُوسُفَ ‏ ‏شَيْخٌ مَكِّيٌّ ‏","","",""],[877,877,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏وَقَيْسٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏إِذَا طَهُرَتْ قَبْلَ الْمَغْرِبِ صَلَّتْ الظُّهْرَ وَالْعَصْرَ وَإِذَا طَهُرَتْ قَبْلَ الْفَجْرِ صَلَّتْ الْمَغْرِبَ وَالْعِشَاءَ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏مِثْلَهُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مِثْلَهُ ‏","","",""],[878,878,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الْحَائِضِ تُصَلِّي الصَّلَاةَ الَّتِي طَهُرَتْ فِي وَقْتِهَا ‏","","",""],[879,879,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَطَاوُسٍ ‏ ‏وَمُجَاهِدٍ ‏ ‏قَالُوا ‏ ‏إِذَا طَهُرَتْ الْحَائِضُ قَبْلَ الْفَجْرِ صَلَّتْ الْمَغْرِبَ وَالْعِشَاءَ وَإِذَا طَهُرَتْ قَبْلَ غُرُوبِ الشَّمْسِ صَلَّتْ الظُّهْرَ وَالْعَصْرَ ‏","","",""],[880,880,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏فِي الْحَائِضِ إِذَا رَأَتْ الطُّهْرَ آخِرَ النَّهَارِ صَلَّتْ الظُّهْرَ وَالْعَصْرَ وَإِذَا طَهُرَتْ آخِرَ اللَّيْلِ صَلَّتْ الْمَغْرِبَ وَالْعِشَاءَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏مِثْلَهُ ‏","","",""],[881,881,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو زَيْدٍ سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏قَالَ كَانَ ‏ ‏إِبْرَاهِيمُ ‏ ‏يَقُولُ ‏ ‏إِذَا طَهُرَتْ عِنْدَ الْعَصْرِ صَلَّتْ الظُّهْرَ وَالْعَصْرَ ‏","","",""],[882,882,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو زَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏شُعْبَةُ ‏ ‏سَأَلْتُ ‏ ‏حَمَّادًا ‏ ‏قَالَ ‏ ‏إِذَا طَهُرَتْ فِي وَقْتِ صَلَاةٍ صَلَّتْ ‏","","",""],[883,883,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏وَحُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا طَهُرَتْ فِي وَقْتِ صَلَاةٍ صَلَّتْ تِلْكَ الصَّلَاةَ وَلَا تُصَلِّي غَيْرَهَا ‏","","",""],[884,884,"","","‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏قَرَأْتُ عَلَى ‏ ‏زَيْدِ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُهُ عَنْ الْمَرْأَةِ تَطْهُرُ بَعْدَ الْعَصْرِ ‏ ‏قَالَ ‏ ‏تُصَلِّي الظُّهْرَ وَالْعَصْرَ قُلْتُ فَإِنْ كَانَ طُهْرُهَا قَرِيبًا مِنْ مَغِيبِ الشَّمْسِ قَالَ تُصَلِّي الْعَصْرَ وَلَا تُصَلِّي الظُّهْرَ وَلَوْ أَنَّهَا لَمْ تَطْهُرْ حَتَّى تَغِيبَ الشَّمْسُ لَمْ يَكُنْ عَلَيْهَا شَيْءٌ ‏ ‏سُئِلَ ‏ ‏عَبْد اللَّهِ ‏ ‏تَأْخُذُ بِهِ ‏ ‏قَالَ ‏ ‏لَا ‏","","",""],[885,885,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ أَبِي الشَّعْثَاءِ الْمُحَارِبِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَتَبَتْ إِلَيْهِ امْرَأَةٌ إِنِّي قَدْ ‏ ‏اسْتُحِضْتُ ‏ ‏مُنْذُ كَذَا وَكَذَا ‏ ‏فَبَلَغَنِي ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏قَالَ ‏ ‏تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَا نَجِدُ لَهَا غَيْرَ مَا قَالَ ‏ ‏عَلِيٌّ ‏","","",""],[886,886,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَوْ ‏ ‏عِكْرِمَةُ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏زَيْنَبُ ‏ ‏تَعْتَكِفُ ‏ ‏مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ ‏ ‏تُرِيقُ ‏ ‏الدَّمَ فَأَمَرَهَا ‏ ‏أَنْ تَغْتَسِلَ عِنْدَ كُلِّ صَلَاةٍ ‏","","",""],[887,887,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏وَابْنَ مَسْعُودٍ ‏ ‏كَانَا يَقُولَانِ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ ‏","","",""],[888,888,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءَ بْنَ أَبِي رَبَاحٍ ‏ ‏يَقُولُ ‏ ‏تَغْتَسِلُ بَيْنَ كُلِّ صَلَاتَيْنِ غُسْلًا وَاحِدًا وَتَغْتَسِلُ لِلْفَجْرِ غُسْلًا وَاحِدًا ‏ ‏قَالَ ‏ ‏الْأَوْزَاعِيُّ ‏ ‏وَكَانَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَمَكْحُولٌ ‏ ‏يَقُولَانِ ‏ ‏تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ ‏","","",""],[889,889,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَوَهْبُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏صَاحِبِ ‏ ‏الدَّسْتَوَائِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ حَبِيبَةَ ‏ ‏قَالَ ‏ ‏وَهْبٌ ‏ ‏أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ ‏ ‏كَانَتْ ‏ ‏تُهَرَاقُ ‏ ‏الدَّمَ وَأَنَّهَا سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَاكَ فَأَمَرَهَا ‏ ‏أَنْ تَغْتَسِلَ عِنْدَ كُلِّ صَلَاةٍ وَتُصَلِّيَ ‏","","",""],[890,890,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يَقُولُ ‏ ‏كَتَبَتْ ‏ ‏امْرَأَةٌ ‏ ‏إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَابْنِ الزُّبَيْرِ ‏ ‏إِنِّي ‏ ‏أُسْتَحَاضُ ‏ ‏فَلَا أَطْهُرُ وَإِنِّي أُذَكِّرُكُمَا اللَّهَ إِلَّا أَفْتَيْتُمَانِي وَإِنِّي سَأَلْتُ عَنْ ذَلِكَ فَقَالُوا كَانَ ‏ ‏عَلِيٌّ ‏ ‏يَقُولُ ‏ ‏تَغْتَسِلُ لِكُلِّ صَلَاةٍ ‏ ‏فَقَرَأْتُ وَكَتَبْتُ الْجَوَابَ بِيَدِي ‏ ‏مَا أَجِدُ لَهَا إِلَّا مَا قَالَ ‏ ‏عَلِيٌّ ‏ ‏فَقِيلَ إِنَّ ‏ ‏الْكُوفَةَ ‏ ‏أَرْضٌ بَارِدَةٌ فَقَالَ ‏ ‏لَوْ شَاءَ اللَّهُ لَابْتَلَاهَا بِأَشَدَّ مِنْ ذَلِكَ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏إِنَّ أَرْضَهَا أَرْضٌ بَارِدَةٌ فَقَالَ تُؤَخِّرُ الظُّهْرَ وَتُعَجِّلُ الْعَصْرَ وَتَغْتَسِلُ غُسْلًا وَتُؤَخِّرُ الْمَغْرِبَ وَتُعَجِّلُ الْعِشَاءَ وَتَغْتَسِلُ غُسْلًا وَتَغْتَسِلُ لِلْفَجْرِ غُسْلًا ‏","","",""],[891,891,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏ابْنَةَ جَحْشٍ ‏ ‏كَانَتْ تَحْتَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏وَكَانَتْ ‏ ‏تُسْتَحَاضُ ‏ ‏فَكَانَتْ تَخْرُجُ مِنْ ‏ ‏مِرْكَنِهَا ‏ ‏وَإِنَّهُ لَعَالِيهِ الدَّمُ فَتُصَلِّي ‏","","",""],[892,892,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ سَعِيدٍ الدِّمَشْقِيُّ ‏ ‏عَنْ ‏ ‏شُعَيْبِ بْنِ إِسْحَقَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏وَيَحْيَى بْنَ أَبِي كَثِيرٍ ‏ ‏يَقُولَانِ ‏ ‏تُفْرِدُ لِكُلِّ صَلَاةٍ اغْتِسَالَةً ‏ ‏قَالَ ‏ ‏الْأَوْزَاعِيُّ ‏ ‏وَبَلَغَنِي ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏مِثْلُ ذَلِكَ ‏","","",""],[893,893,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَانَ يَقُولُ ‏ ‏لِكُلِّ صَلَاتَيْنِ اغْتِسَالَةٌ وَتُفْرِدُ لِصَلَاةِ الصُّبْحِ اغْتِسَالَةً ‏","","",""],[894,894,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ الْكُوفِيِّ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَقَالَتْ إِنِّي ‏ ‏أُسْتَحَاضُ ‏ ‏فَقَالَ ‏ ‏عَلَيْكِ بِالْمَاءِ ‏ ‏فَانْضَحِيهِ ‏ ‏فَإِنَّهُ يَقْطَعُ الدَّمَ عَنْكِ ‏","","",""],[895,895,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَفَّانُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ دِينَارٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الْمُطَلَّقَةِ الَّتِي ‏ ‏ارْتِيبَ ‏ ‏بِهَا ‏ ‏تَرَبَّصُ ‏ ‏سَنَةً فَإِنْ حَاضَتْ وَإِلَّا ‏ ‏تَرَبَّصَتْ ‏ ‏بَعْدَ انْقِضَاءِ السَّنَةِ ثَلَاثَةَ أَشْهُرٍ فَإِنْ حَاضَتْ وَإِلَّا فَقَدْ انْقَضَتْ عِدَّتُهَا ‏","","",""],[896,896,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏مَالِكٌ ‏ ‏عَنْ عِدَّةِ ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏إِذَا طُلِّقَتْ ‏ ‏فَحَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُ قَالَ ‏ ‏عِدَّتُهَا سَنَةٌ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هُوَ قَوْلُ ‏ ‏مَالِكٍ ‏","","",""],[897,897,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏جَابِرُ بْنُ زَيْدٍ ‏ ‏عَنْ الْمَرْأَةِ تُطَلَّقُ وَهِيَ شَابَّةٌ فَتَرْتَفِعُ حِيضَتُهَا مِنْ غَيْرِ كِبَرٍ قَالَ ‏ ‏مِنْ غَيْرِ حَيْضٍ ‏ ‏تَحَيَّضُ ‏ ‏وَقَالَ ‏ ‏طَاوُسٌ ‏ ‏ثَلَاثَةَ أَشْهُرٍ ‏","","",""],[898,898,"","","‏ ‏أَخْبَرَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏إِذَا طَلَّقَ الرَّجُلُ امْرَأَتَهُ فَحَاضَتْ حَيْضَةً أَوْ حَيْضَتَيْنِ ثُمَّ ارْتَفَعَتْ حَيْضَتُهَا إِنْ كَانَ ذَلِكَ مِنْ كِبَرٍ اعْتَدَّتْ ثَلَاثَةَ أَشْهُرٍ وَإِنْ كَانَتْ شَابَّةً ‏ ‏وَارْتَابَتْ ‏ ‏اعْتَدَّتْ سَنَةً بَعْدَ ‏ ‏الرِّيبَةِ ‏","","",""],[899,899,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ ‏ ‏حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏وَالَّتِي لَا يَسْتَقِيمُ لَهَا حَيْضٌ فَتَحِيضُ فِي شَهْرٍ مَرَّةً وَفِي الشَّهْرِ مَرَّتَيْنِ عِدَّتُهَا ثَلَاثَةُ أَشْهُرٍ ‏","","",""],[900,900,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏قَالَ ‏ ‏تَعْتَدُّ ‏ ‏بِالْأَقْرَاءِ ‏","","",""],[901,901,"","","‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏عِدَّةُ ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏سَنَةٌ ‏","","",""],[902,902,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَعْتَدُّ ‏ ‏بِالْأَقْرَاءِ ‏","","",""],[903,903,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَلِيفَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏بِالْأَقْرَاءِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَهْلُ ‏ ‏الْحِجَازِ ‏ ‏يَقُولُونَ الْأَقْرَاءُ الْأَطْهَارُ وَقَالَ أَهْلُ ‏ ‏الْعِرَاقِ ‏ ‏هُوَ الْحَيْضُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَأَنَا أَقُولُ هُوَ الْحَيْضُ ‏","","",""],[904,904,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏تَعْتَدُّ ‏ ‏بِالْأَقْرَاءِ ‏","","",""],[905,905,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏الْهِقْلِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ وَهِيَ شَابَّةٌ تَحِيضُ فَانْقَطَعَ عَنْهَا الْمَحِيضُ حِينَ طَلَّقَهَا فَلَمْ تَرَ دَمًا كَمْ تَعْتَدُّ قَالَ ثَلَاثَةَ أَشْهُرٍ قَالَ وَسَأَلْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ فَحَاضَتْ حَيْضَتَيْنِ ثُمَّ ارْتَفَعَتْ حَيْضَتُهَا كَمْ ‏ ‏تَرَبَّصُ ‏ ‏قَالَ عِدَّتُهَا سَنَةٌ قَالَ وَسَأَلْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ وَهِيَ تَحِيضُ تَمْكُثُ ثَلَاثَةَ أَشْهُرٍ ثُمَّ تَحِيضُ حَيْضَةً ثُمَّ يَتَأَخَّرُ عَنْهَا الْحَيْضُ ثُمَّ تَمْكُثُ السَّبْعَةَ الْأَشْهُرَ وَالثَّمَانِيَةَ ثُمَّ تَحِيضُ أُخْرَى تَسْتَعْجِلُ إِلَيْهَا مَرَّةً وَتَسْتَأْخِرُ أُخْرَى كَيْفَ تَعْتَدُّ قَالَ إِذَا اخْتَلَفَتْ حِيضَتُهَا عَنْ ‏ ‏أَقْرَائِهَا ‏ ‏فَعِدَّتُهَا سَنَةٌ قُلْتُ وَكَيْفَ إِنْ كَانَ طَلَّقَ وَهِيَ تَحِيضُ فِي كُلِّ سَنَةٍ مَرَّةً كَمْ تَعْتَدُّ قَالَ إِنْ كَانَتْ تَحِيضُ ‏ ‏أَقْرَاؤُهَا ‏ ‏مَعْلُومَةٌ هِيَ ‏ ‏أَقْرَاؤُهَا ‏ ‏فَإِنَّا نُرَى أَنْ تَعْتَدَّ ‏ ‏أَقْرَاءَهَا ‏","","",""],[906,906,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عَبْدِ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ ‏ ‏الرَّجُلِ يَبْتَاعُ الْجَارِيَةَ لَمْ تَبْلُغْ الْمَحِيضَ وَلَا تَحْمِلُ مِثْلُهَا بِكَمْ ‏ ‏يَسْتَبْرِئُهَا ‏ ‏قَالَ بِثَلَاثَةِ أَشْهُرٍ ‏ ‏وَقَالَ ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏بِخَمْسَةٍ وَأَرْبَعِينَ يَوْمًا ‏","","",""],[907,907,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتَوَائِيِّ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ يَقُولُ فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ وَتُصَلِّي ‏ ‏وَقَالَ ‏ ‏حَمَّادٌ ‏ ‏لَوْ أَنَّ ‏ ‏مُسْتَحَاضَةً ‏ ‏جَهِلَتْ فَتَرَكَتْ الصَّلَاةَ أَشْهُرًا فَإِنَّهَا تَقْضِي تِلْكَ الصَّلَوَاتِ قِيلَ لَهُ وَكَيْفَ ‏ ‏تَقْضِيهَا قَالَ ‏ ‏تَقْضِيهَا فِي يَوْمٍ وَاحِدٍ إِنْ اسْتَطَاعَتْ ‏ ‏قِيلَ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏تَقُولُ بِهِ ‏ ‏قَالَ ‏ ‏إِي وَاللَّهِ ‏","","",""],[908,908,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ الْحَامِلِ ‏ ‏تَرَى الدَّمَ فَقَالَ ‏ ‏تَدَعُ الصَّلَاةَ ‏","","",""],[909,909,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْأَسْوَدِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏مُجَاهِدًا ‏ ‏عَنْ امْرَأَتِي رَأَتْ دَمًا وَأَنَا أُرَاهَا حَامِلًا قَالَ ‏ ‏ذَلِكَ ‏ ‏غَيْضُ ‏ ‏الْأَرْحَامِ ‏ { ‏اللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنْثَى وَمَا ‏ ‏تَغِيضُ ‏ ‏الْأَرْحَامُ وَمَا تَزْدَادُ ‏} ‏فَمَا ‏ ‏غَاضَتْ ‏ ‏مِنْ شَيْءٍ رَأَتْ مِثْلَهُ فِي الْحَمْلِ ‏","","",""],[910,910,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏فِي هَذِهِ الْآيَةِ ‏ { ‏اللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنْثَى وَمَا ‏ ‏تَغِيضُ ‏ ‏الْأَرْحَامُ وَمَا تَزْدَادُ وَكُلُّ شَيْءٍ عِنْدَهُ بِمِقْدَارٍ ‏} ‏قَالَ ‏ ‏ذَلِكَ الْحَيْضُ عَلَى الْحَبَلِ لَا تَحِيضُ يَوْمًا فِي الْحَبَلِ إِلَّا زَادَتْهُ طَاهِرًا فِي حَبَلِهَا ‏","","",""],[911,911,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَمْرٌ لَا يُخْتَلَفُ فِيهِ عِنْدَنَا عَنْ ‏ ‏عَائِشَةَ ‏ ‏الْمَرْأَةُ الْحُبْلَى إِذَا رَأَتْ الدَّمَ أَنَّهَا لَا تُصَلِّي حَتَّى تَطْهُرَ ‏","","",""],[912,912,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ { ‏وَمَا ‏ ‏تَغِيضُ ‏ ‏الْأَرْحَامُ ‏} ‏قَالَ هُوَ الْحَيْضُ عَلَى الْحَبَلِ ‏ { ‏وَمَا تَزْدَادُ ‏} ‏قَالَ فَلَهَا بِكُلِّ يَوْمٍ حَاضَتْ فِي حَمْلِهَا يَوْمًا تَزْدَادُ فِي طُهْرِهَا حَتَّى تَسْتَكْمِلَ تِسْعَةَ أَشْهُرٍ طَاهِرًا ‏","","",""],[913,913,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ { ‏وَمَا ‏ ‏تَغِيضُ ‏ ‏الْأَرْحَامُ ‏} ‏قَالَ إِذَا حَاضَتْ الْمَرْأَةُ وَهِيَ حَامِلٌ قَالَ يَكُونُ ذَلِكَ نُقْصَانًا مِنْ الْوَلَدِ فَإِذَا زَادَتْ عَلَى تِسْعَةِ أَشْهُرٍ كَانَ تَمَامًا لِمَا نَقَصَ مِنْ وَلَدِهَا ‏","","",""],[914,914,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏امْرَأَتِي تَحِيضُ وَهِيَ حُبْلَى ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ حَرْبٍ ‏ ‏يَقُولُ امْرَأَتِي تَحِيضُ وَهِيَ حُبْلَى ‏","","",""],[915,915,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِذَا رَأَتْ الْحُبْلَى الدَّمَ فَلْتُمْسِكْ عَنْ الصَّلَاةِ فَإِنَّهُ حَيْضٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏أَنَّهُ ‏ ‏بَلَغَهُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلُ ذَلِكَ ‏","","",""],[916,916,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبَانَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي الْحَامِلِ ‏ ‏تَرَى الدَّمَ إِنْ كَانَ الدَّمُ ‏ ‏عَبِيطًا ‏ ‏اغْتَسَلَتْ وَصَلَّتْ وَإِنْ كَانَتْ ‏ ‏تَرِيَّةً ‏ ‏تَوَضَّأَتْ وَصَلَّتْ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏مِثْلَهُ ‏","","",""],[917,917,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ هُوَ ابْنُ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِنْ كَانَتْ تَرَاهُ كَمَا كَانَتْ تَرَاهُ قَبْلَ ذَلِكَ فِي ‏ ‏أَقْرَائِهَا ‏ ‏تَرَكَتْ الصَّلَاةَ وَإِنْ كَانَ إِنَّمَا هُوَ فِي الْيَوْمِ أَوْ الْيَوْمَيْنِ لَمْ تَدَعْ الصَّلَاةَ ‏","","",""],[918,918,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ هُوَ ابْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏وَعَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فِي الْحَامِلِ ‏ ‏تَرَى الدَّمَ قَالَتْ لَا يَمْنَعُهَا ذَلِكَ مِنْ صَلَاةٍ ‏","","",""],[919,919,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فِي الْحَامِلِ ‏ ‏تَرَى الدَّمَ قَالَتْ تَغْتَسِلُ وَتُصَلِّي ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏لَا تَغْتَسِلُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏أَقُولُ بِقَوْلِ ‏ ‏يَزِيدَ ‏","","",""],[920,920,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الْحَامِلِ ‏ ‏تَرَى الدَّمَ قَالَ ‏ ‏هِيَ بِمَنْزِلَةِ ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏غَيْرَ أَنَّهَا لَا تَدَعُ الصَّلَاةَ ‏","","",""],[921,921,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْحَامِلِ ‏ ‏تَرَى الدَّمَ ‏ ‏قَالَ ‏ ‏تَغْسِلُ عَنْهَا الدَّمَ وَتَتَوَضَّأُ وَتُصَلِّي ‏","","",""],[922,922,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَالْحَكَمِ ‏ ‏قَالَا ‏ ‏إِذَا رَأَتْ الْحَامِلُ الدَّمَ تَوَضَّأَتْ وَصَلَّتْ ‏","","",""],[923,923,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَامِعٍ هُوَ ابْنُ أَبِي رَاشِدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْحَامِلِ ‏ ‏تَرَى الدَّمَ قَالَ ‏ ‏تَوَضَّأُ وَتُصَلِّي ‏","","",""],[924,924,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏هِيَ بِمَنْزِلَةِ ‏ ‏الْمُسْتَحَاضَةِ ‏","","",""],[925,925,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لَا يَكُونُ حَيْضٌ عَلَى حَمْلٍ ‏","","",""],[926,926,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الْحَامِلِ ‏ ‏تَرَى الدَّمَ ‏ ‏قَالَ ‏ ‏هِيَ بِمَنْزِلَةِ ‏ ‏الْمُسْتَحَاضَةِ ‏","","",""],[927,927,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِذَا رَأَتْ الْحَامِلُ الدَّمَ لَمْ تَدَعْ الصَّلَاةَ ‏","","",""],[928,928,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَالْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏أَنَّهُمَا قَالَا ‏ ‏فِي الْحُبْلَى وَالَّتِي قَعَدَتْ عَنْ الْمَحِيضِ إِذَا رَأَتْ الدَّمَ تَوَضَّأَتَا وَصَلَّتَا وَلَا تَغْتَسِلَانِ ‏","","",""],[929,929,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏تَغْتَسِلَانِ وَتُصَلِّيَانِ ‏","","",""],[930,930,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى الدِّمَشْقِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ الْحُبْلَى لَا تَحِيضُ فَإِذَا رَأَتْ الدَّمَ فَلْتَغْتَسِلْ وَلْتُصَلِّ ‏","","",""],[931,931,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْفُضَيْلِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْمَرْأَةِ إِذَا رَأَتْ الدَّمَ وَهِيَ ‏ ‏تَمَخَّضُ ‏ ‏قَالَ هُوَ حَيْضٌ تَتْرُكُ الصَّلَاةَ ‏","","",""],[932,932,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الْمَرْأَةِ الْحَامِلِ إِذَا ضَرَبَهَا الطَّلْقُ وَرَأَتْ الدَّمَ عَلَى الْوَلَدِ فَلْتُمْسِكْ عَنْ الصَّلَاةِ ‏ ‏و قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏تُصَلِّي مَا لَمْ تَضَعْ ‏","","",""],[933,933,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏فِي النُّفَسَاءِ كَطُهْرِ امْرَأَةٍ مِنْ نِسَائِهَا ‏","","",""],[934,934,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي النُّفَسَاءِ تُمْسِكُ عَنْ الصَّلَاةِ أَرْبَعِينَ يَوْمًا فَإِنْ رَأَتْ الطُّهْرَ فَذَاكَ وَإِنْ لَمْ تَرَ الطُّهْرَ أَمْسَكَتْ عَنْ الصَّلَاةِ أَيَّامًا خَمْسًا سِتًّا فَإِنْ طَهُرَتْ فَذَاكَ وَإِلَّا أَمْسَكَتْ عَنْ الصَّلَاةِ مَا بَيْنَهَا وَبَيْنَ الْخَمْسِينَ فَإِنْ طَهُرَتْ فَذَاكَ وَإِلَّا فَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[935,935,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏أَنَّهُ كَانَ ‏ ‏لَا يَقْرَبُ النُّفَسَاءَ أَرْبَعِينَ يَوْمًا ‏ ‏و قَالَ ‏ ‏الْحَسَنُ ‏ ‏النُّفَسَاءُ خَمْسَةٌ وَأَرْبَعُونَ إِلَى خَمْسِينَ فَمَا زَادَ فَهِيَ ‏ ‏مُسْتَحَاضَةٌ ‏","","",""],[936,936,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏قَالَ ‏ ‏وَقْتُ النُّفَسَاءِ أَرْبَعِينَ يَوْمًا فَإِنْ طَهُرَتْ وَإِلَّا فَلَا تُجَاوِزْهُ حَتَّى تُصَلِّيَ ‏","","",""],[937,937,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏إِنْ كَانَ لِلنُّفَسَاءِ عَادَةٌ وَإِلَّا جَلَسَتْ أَرْبَعِينَ لَيْلَةً ‏","","",""],[938,938,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏النِّفَاسُ حَيْضٌ ‏","","",""],[939,939,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَنْتَظِرُ النُّفَسَاءُ أَرْبَعِينَ يَوْمًا أَوْ نَحْوَهَا ‏","","",""],[940,940,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ الْبَصْرِيِّ ‏ ‏عَنْ ‏ ‏مُسَّةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ النُّفَسَاءُ تَجْلِسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعِينَ يَوْمًا أَوْ أَرْبَعِينَ لَيْلَةً وَكَانَتْ إِحْدَانَا ‏ ‏تَطْلِي ‏ ‏الْوَرْسَ ‏ ‏عَلَى وَجْهِهَا مِنْ ‏ ‏الْكَلَفِ ‏","","",""],[941,941,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏جَلْدٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏أَنَّ امْرَأَةً ‏ ‏لِعَائِذِ بْنِ عَمْرٍو ‏ ‏نُفِسَتْ فَجَاءَتْ بَعْدَمَا مَضَتْ عِشْرُونَ لَيْلَةً فَدَخَلَتْ فِي لِحَافِهِ فَقَالَ مَنْ هَذِهِ قَالَتْ أَنَا فُلَانَةُ إِنِّي قَدْ تَطَهَّرْتُ ‏ ‏فَرَكَضَهَا ‏ ‏بِرِجْلِهِ فَقَالَ ‏ ‏لَا تُغَرِّنِي عَنْ دِينِي حَتَّى تَمْضِيَ أَرْبَعُونَ لَيْلَةً ‏","","",""],[942,942,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏النُّفَسَاءُ تَجْلِسُ نَحْوًا مِنْ أَرْبَعِينَ ‏","","",""],[943,943,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏النُّفَسَاءُ تَنْتَظِرُ نَحْوًا مِنْ أَرْبَعِينَ يَوْمًا ‏","","",""],[944,944,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏الْحَسَنَ ‏ ‏قَالَ ‏ ‏فِي النُّفَسَاءِ الَّتِي ‏ ‏تَرَى الدَّمَ ‏ ‏تَرَبَّصُ ‏ ‏أَرْبَعِينَ لَيْلَةً ثُمَّ تُصَلِّي ‏ ‏وَقَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏شَهْرَيْنِ ثُمَّ هِيَ بِمَنْزِلَةِ ‏ ‏الْمُسْتَحَاضَةِ ‏","","",""],[945,945,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ شُعَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سُلَيْمَانَ الْأَفْطَسُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ بْنَ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏قَالَ ‏ ‏الْمَرْأَةُ تَنْتَظِرُ مِنْ الْغُلَامِ ثَلَاثِينَ يَوْمًا وَمِنْ الْجَارِيَةِ أَرْبَعِينَ يَوْمًا ‏ ‏يَعْنِي النُّفَسَاءَ ‏ ‏قَالَ ‏ ‏مَرْوَانُ ‏ ‏هُوَ قَوْلُ ‏ ‏سَعِيدِ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏و قَالَ ‏ ‏الْأَوْزَاعِيُّ ‏ ‏هُمَا سَوَاءٌ ‏","","",""],[946,946,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا رَأَتْ الدَّمَ عِنْدَ ‏ ‏الطَّلْقِ ‏ ‏يَوْمًا أَوْ يَوْمَيْنِ فَهُوَ مِنْ النِّفَاسِ ‏","","",""],[947,947,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْحَامِلِ ‏ ‏تَرَى الدَّمَ وَهِيَ ‏ ‏تَطْلُقُ ‏ ‏قَالَ تَصْنَعُ مَا تَصْنَعُ ‏ ‏الْمُسْتَحَاضَةُ ‏","","",""],[948,948,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْمَرْأَةِ تُجْنِبُ ثُمَّ تَحِيضُ قَالَ تَغْتَسِلُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏مِثْلَهُ ‏","","",""],[949,949,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏الْحَيْضُ أَكْبَرُ ‏","","",""],[950,950,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي رَجُلٍ ‏ ‏غَشِيَ ‏ ‏امْرَأَتَهُ فَحَاضَتْ فَقَالَ تَغْتَسِلُ أَحَبُّ إِلَيَّ ‏","","",""],[951,951,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَالنَّخَعِيِّ ‏ ‏قَالَا ‏ ‏لِتَغْتَسِلْ مِنْ الْجَنَابَةِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[952,952,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ الْمُسَيَّبِ ‏ ‏قَالَ سُئِلَ عَنْهَا ‏ ‏حَمَّادٌ ‏ ‏فَقَالَ قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏تَغْتَسِلُ ‏","","",""],[953,953,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏ابْنِ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏تَغْتَسِلُ ‏","","",""],[954,954,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَكَمَ بْنَ عُتَيْبَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏يُعْجِبُهُمْ فِي الْمَرْأَةِ الْحَائِضِ أَنْ تَوَضَّأَ وُضُوءَهَا لِلصَّلَاةِ ثُمَّ تُسَبِّحَ اللَّهَ وَتُكَبِّرَهُ فِي وَقْتِ الصَّلَاةِ ‏","","",""],[955,955,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَبِي قِلَابَةَ ‏ ‏الْحَائِضُ تَتَوَضَّأُ عِنْدَ وَقْتِ كُلِّ صَلَاةٍ وَتَذْكُرُ اللَّهَ فَقَالَ مَا وَجَدْتُ لِهَذَا أَصْلًا ‏","","",""],[956,956,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خَالِدُ بْنُ يَزِيدَ الصَّدَفِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَأْمُرُ الْمَرْأَةَ الْحَائِضَ عِنْدَ أَوَانِ الصَّلَاةِ أَنْ تَوَضَّأَ وَتَجْلِسَ ‏ ‏بِفِنَاءِ مَسْجِدِهَا ‏ ‏فَتَذْكُرَ اللَّهَ وَتُسَبِّحَ ‏","","",""],[957,957,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْمَرْأَةِ الْحَائِضِ أَتَقْرَأُ ‏ ‏قَالَ ‏ ‏لَا إِلَّا طَرَفَ الْآيَةِ وَلَكِنْ تَوَضَّأُ عِنْدَ وَقْتِ كُلِّ صَلَاةٍ ثُمَّ تَسْتَقْبِلُ الْقِبْلَةَ وَتُسَبِّحُ وَتُكَبِّرُ وَتَدْعُو اللَّهَ ‏","","",""],[958,958,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ضَمْرَةُ ‏ ‏حَدَّثَنَا ‏ ‏السَّيْبَانِيُّ وَهُوَ يَحْيَى بْنُ أَبِي عَمْرٍو ‏ ‏مِنْ أَهْلِ ‏ ‏الرَّمْلَةِ ‏ ‏حَدَّثَنَا ‏ ‏مَكْحُولٌ ‏ ‏قَالَ ‏ ‏تُؤْمَرُ الْحَائِضُ تَتَوَضَّأُ عِنْدَ مَوَاقِيتِ الصَّلَاةِ وَتَسْتَقْبِلُ الْقِبْلَةَ وَتَذْكُرُ اللَّهَ ‏","","",""],[959,959,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعَ الْحَائِضُ وَالْجُنُبُ السَّجْدَةَ يَغْتَسِلُ الْجُنُبُ وَيَسْجُدُ وَلَا تَقْضِي الْحَائِضُ لِأَنَّهَا لَا تُصَلِّي ‏","","",""],[960,960,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْحَائِضِ تَسْمَعُ السَّجْدَةَ قَالَ لَا تَقْضِي ‏","","",""],[961,961,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏وَجَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لَيْسَ عَلَيْهَا شَيْءٌ ‏","","",""],[962,962,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ بْنُ مُعَتِّبٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنَّا ‏ ‏نَحِيضُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا يَأْمُرُ امْرَأَةً مِنَّا بِرَدِّ الصَّلَاةِ ‏","","",""],[963,963,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏أَتَقْضِي إِحْدَانَا صَلَاةَ أَيَّامِ حَيْضِهَا فَقَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قَدْ كَانَتْ إِحْدَانَا تَحِيضُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا تُؤْمَرُ بِقَضَاءٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏قَالَ ‏ ‏أَبُو النُّعْمَانِ ‏ ‏كَأَنَّ ‏ ‏حَمَّادًا ‏ ‏فَرِقَ حَدِيثَ ‏ ‏أَيُّوبَ ‏ ‏فَجَاءَ بِهَذَا ‏","","",""],[964,964,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعَتْ الْحَائِضُ السَّجْدَةَ فَلَا تَسْجُدْ ‏","","",""],[965,965,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ ‏ ‏لَا تَسْجُدُ الْمَرْأَةُ الْحَائِضُ إِذَا سَمِعَتْ السَّجْدَةَ ‏","","",""],[966,966,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَكْرَهُ لِلْحَائِضِ أَنْ تَسْجُدَ إِذَا سَمِعَتْ السَّجْدَةَ ‏","","",""],[967,967,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ عَجْلَانَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ النُّفَسَاءِ وَالْحَائِضِ هَلْ تَقْضِيَانِ الصَّلَاةَ إِذَا تَطَهَّرْنَ قَالَ ‏ ‏هُوَ ذَا أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَوْ فَعَلْنَ ذَلِكَ أَمَرْنَا نِسَاءَنَا بِذَلِكَ ‏","","",""],[968,968,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَتْ امْرَأَةٌ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ أَقْضِي مَا تَرَكْتُ مِنْ صَلَوَاتِي فِي الْحَيْضِ عِنْدَ الطُّهْرِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَتْ إِحْدَانَا تَحِيضُ وَتَطْهُرُ فَلَا يَأْمُرُنَا بِالْقَضَاءِ ‏","","",""],[969,969,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏كَثِيرٍ أَبِي إِسْمَعِيلَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِفَاطِمَةَ يَعْنِي بِنْتَ عَلِيٍّ ‏ ‏أَتَقْضِينَ صَلَاةَ أَيَّامِ حَيْضِكِ قَالَتْ لَا ‏","","",""],[970,970,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏سَأَلَتْهَا امْرَأَةٌ ‏ ‏أَتَقْضِي الْحَائِضُ الصَّلَاةَ قَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قَدْ حِضْنَ نِسَاءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُنَّ يَجْزِينَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏مَعْنَاهُ أَنَّهُنَّ لَا يَقْضِينَ ‏","","",""],[971,971,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْحَائِضُ وَالْجُنُبُ يَذْكُرَانِ اللَّهَ وَيُسَمِّيَانِ ‏","","",""],[972,972,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏بَلَغَنِي ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَسَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُمَا قَالَا ‏ ‏لَا يَقْرَأْ الْجُنُبُ وَالْحَائِضُ آيَةً تَامَّةً يَقْرَأَانِ الْحَرْفَ ‏","","",""],[973,973,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْبَزَّازُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏الْجُنُبُ وَالْحَائِضُ لَا يَقْرَأَانِ الْقُرْآنَ ‏","","",""],[974,974,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُمَرُ ‏ ‏يَكْرَهُ أَوْ ‏ ‏يَنْهَى أَنْ يَقْرَأَ الْجُنُبُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَجَدْتُ فِي الْكِتَابِ وَالْحَائِضُ ‏","","",""],[975,975,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتَوَائِيِّ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏أَرْبَعَةٌ لَا يَقْرَءُونَ الْقُرْآنَ عِنْدَ الْخَلَاءِ وَفِي الْحَمَّامِ وَالْجُنُبُ وَالْحَائِضُ إِلَّا الْآيَةَ وَنَحْوَهَا لِلْجُنُبِ وَالْحَائِضِ ‏","","",""],[976,976,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَحَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَسَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالُوا ‏ ‏الْحَائِضُ وَالْجُنُبُ يَسْتَفْتِحُونَ الْآيَةَ وَلَا يُتِمُّونَ آخِرَهَا ‏","","",""],[977,977,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏فِي الْحَائِضِ ‏ ‏قَالَ ‏ ‏لَا تَقْرَأُ الْقُرْآنَ ‏","","",""],[978,978,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏السَّائِبُ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏كَانَتْ ‏ ‏تَرْقِي ‏ ‏أَسْمَاءَ ‏ ‏وَهِيَ ‏ ‏عَارِكٌ ‏","","",""],[979,979,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ ‏ ‏الْجُنُبُ يَذْكُرُ اسْمَ اللَّهِ ‏","","",""],[980,980,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَيَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏كَانَ يُقَالُ ‏ ‏لَا يَقْرَأُ الْجُنُبُ وَلَا الْحَائِضُ وَلَا يُقْرَأُ فِي الْحَمَّامِ وَحَالَانِ لَا يَذْكُرُ الْعَبْدُ فِيهِمَا اللَّهَ عِنْدَ الْخَلَاءِ وَعِنْدَ الْجِمَاعِ إِلَّا أَنَّ الرَّجُلَ إِذَا ‏ ‏أَتَى ‏ ‏أَهْلَهُ بَدَأَ فَسَمَّى اللَّهَ ‏","","",""],[981,981,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْمَرْأَةِ الْحَائِضِ تَقْرَأُ ‏ ‏قَالَ ‏ ‏لَا إِلَّا طَرَفَ الْآيَةِ ‏","","",""],[982,982,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَطَّافٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَرْبَعٌ لَا يَحْرُمْنَ عَلَى جُنُبٍ وَلَا حَائِضٍ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ ‏ ‏سُئِلَ ‏ ‏أَبُو مُحَمَّد ‏ ‏عَبْد اللَّهِ ‏ ‏يَقْرَأُ الْجُنُبُ آيَةً آيَةً ‏ ‏قَالَ ‏ ‏لَا يُعْجِبُنِي ‏","","",""],[983,983,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحِيمِ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ صُبَيْحٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ سُئِلَ عَنْ الْحَائِضِ تَسْمَعُ السَّجْدَةَ قَالَ ‏ ‏لَا تَسْجُدُ لِأَنَّهَا صَلَاةٌ ‏","","",""],[984,984,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَأَبِي الضُّحَى ‏ ‏قَالَا ‏ ‏لَا تَسْجُدُ ‏","","",""],[985,985,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَسَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَا ‏ ‏لَيْسَ عَلَيْهَا ذَاكَ الصَّلَاةُ أَكْبَرُ مِنْ ذَلِكَ ‏","","",""],[986,986,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏مُنِعَتْ خَيْرًا مِنْ ذَلِكَ الصَّلَاةَ الْمَكْتُوبَةَ ‏","","",""],[987,987,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏لَا تَسْجُدُ ‏","","",""],[988,988,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏فِي الْمَرْأَةِ ‏ ‏تَرَى الطُّهْرَ فَتَسْمَعُ السَّجْدَةَ قَالَ ‏ ‏لَا تَسْجُدُ حَتَّى تَغْتَسِلَ ‏","","",""],[989,989,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو زَيْدٍ سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ذَرًّا ‏ ‏عَنْ ‏ ‏وَائِلِ بْنِ مُهَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لِلنِّسَاءِ ‏ ‏تَصَدَّقْنَ فَإِنَّكُنَّ أَكْثَرُ أَهْلِ النَّارِ فَقَالَتْ امْرَأَةٌ لَيْسَتْ مِنْ عِلْيَةِ النِّسَاءِ لِمَ ‏ ‏أَوْ بِمَ أَوْ فِيمَ ‏ ‏قَالَ إِنَّكُنَّ تُكْثِرْنَ اللَّعْنَ ‏ ‏وَتَكْفُرْنَ الْعَشِيرَ ‏ ‏قَالَ وَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَا مِنْ نَاقِصِي الدِّينِ وَالْعَقْلِ أَغْلَبَ لِلرِّجَالِ ذَوِي الْأَمْرِ عَلَى أَمْرِهِمْ مِنْ النِّسَاءِ ‏ ‏قَالَ رَجُلٌ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏مَا نُقْصَانُ عَقْلِهَا ‏ ‏قَالَ ‏ ‏جُعِلَتْ شَهَادَةُ امْرَأَتَيْنِ بِشَهَادَةِ رَجُلٍ قَالَ سُئِلَ مَا نُقْصَانُ دِينِهَا قَالَ تَمْكُثُ كَذَا وَكَذَا مِنْ يَوْمٍ وَلَيْلَةٍ لَا تُصَلِّي لِلَّهِ صَلَاةً ‏","","",""],[990,990,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِذَا طَهُرَتْ الْمَرْأَةُ مِنْ الْحَيْضِ فَلْتَتَّبِعْ ثَوْبَهَا الَّذِي يَلِي جِلْدَهَا فَلْتَغْسِلْ مَا أَصَابَهُ مِنْ الْأَذَى ثُمَّ تُصَلِّي فِيهِ ‏","","",""],[991,991,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏يَكُونُ لِإِحْدَانَا ‏ ‏الدِّرْعُ ‏ ‏فِيهِ تَحِيضُ وَفِيهِ تُجْنِبُ ثُمَّ ‏ ‏تَرَى فِيهِ الْقَطْرَةَ مِنْ دَمِ حَيْضَتِهَا ‏ ‏فَتَقْصَعُهُ ‏ ‏بِرِيقِهَا ‏","","",""],[992,992,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْهُذَلِيُّ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏إِنَّ إِحْدَاكُنَّ تَسْبِقُهَا الْقَطْرَةُ مِنْ الدَّمِ فَإِذَا أَصَابَتْ إِحْدَاكُنَّ ذَلِكَ ‏ ‏فَلْتَقْصَعْهُ ‏ ‏بِرِيقِهَا ‏","","",""],[993,993,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ الْعَدَوِيَّةِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِذَا غَسَلَتْ الْمَرْأَةُ الدَّمَ فَلَمْ يَذْهَبْ فَلْتُغَيِّرْهُ بِصُفْرَةِ ‏ ‏وَرْسٍ ‏ ‏أَوْ زَعْفَرَانٍ ‏","","",""],[994,994,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاذَةَ الْعَدَوِيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ لَهَا امْرَأَةٌ الدَّمُ يَكُونُ فِي الثَّوْبِ فَأَغْسِلُهُ فَلَا يَذْهَبُ فَأُقَطِّعُهُ ‏ ‏قَالَتْ ‏ ‏الْمَاءُ طَهُورٌ ‏","","",""],[995,995,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرُ بْنُ صُبْحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خِلَاسَ بْنَ عَمْرٍو ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏يَكُونُ مَعِي فِي الشِّعَارِ الْوَاحِدِ وَأَنَا حَائِضٌ طَامِثٌ إِنْ أَصَابَهُ مِنِّي شَيْءٌ غَسَلَ مَا أَصَابَهُ لَمْ يَعْدُهُ إِلَى غَيْرِهِ وَصَلَّى فِيهِ ثُمَّ يَعُودُ وَإِنْ أَصَابَهُ مِنِّي شَيْءٌ فَعَلَ مِثْلَ ذَلِكَ غَسَلَ مَكَانَهُ لَمْ يَعْدُهُ إِلَى غَيْرِهِ وَصَلَّى فِيهِ ‏","","",""],[996,996,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتَوَائِيِّ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِيمَا تَلْبَسُ الْمَرْأَةُ مِنْ الثِّيَابِ وَهِيَ حَائِضٌ إِنْ أَصَابَهُ دَمٌ غَسَلَتْهُ وَإِلَّا فَلَيْسَ عَلَيْهَا غَسْلُهُ وَإِنْ عَرِقَتْ فِيهِ فَإِنَّهُ يُجْزِئُهَا أَنْ تَنْضَحَهُ ‏","","",""],[997,997,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏الْمَرْأَةُ الْحَائِضُ تُصَلِّي فِي ثِيَابِهَا الَّتِي تَحِيضُ فِيهَا إِلَّا أَنْ يُصِيبَ شَيْئًا مِنْهَا دَمٌ فَتَغْسِلَ مَوْضِعَ الدَّمِ ‏","","",""],[998,998,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ دَمِ الْحَيْضِ يُصِيبُ الثَّوْبَ قَالَ ‏ ‏حُتِّيهِ ثُمَّ رُشِّيهِ بِالْمَاءِ ‏","","",""],[999,999,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هَانِئٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ طَهْمَانَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْحَائِضُ لَا تَغْسِلُ ثَوْبَهَا إِذَا لَمْ يَكُنْ فِيهِ دَمٌ ‏","","",""],[1000,1000,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ هُوَ ابْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ إِسْحَقَ ‏ ‏حَدَّثَتْنِي ‏ ‏فَاطِمَةُ بِنْتُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ امْرَأَةً تَسْأَلُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ثَوْبِهَا إِذَا طَهُرَتْ مِنْ مَحِيضِهَا كَيْفَ تَصْنَعُ بِهِ قَالَ ‏ ‏إِنْ رَأَيْتِ فِيهِ دَمًا فَحُكِّيهِ ثُمَّ اقْرُصِيهِ بِمَاءٍ ثُمَّ انْضَحِي فِي سَائِرِهِ فَصَلِّي فِيهِ ‏","","",""]];
